import React, { useState, useRef } from 'react';
import axios from 'axios';
import { useAuth } from '../context/AuthContext';

const CreatePost = ({ onPostCreated }) => {
  const [content, setContent] = useState('');
  const [mediaFiles, setMediaFiles] = useState([]);
  const [mediaPreviews, setMediaPreviews] = useState([]);
  const [loading, setLoading] = useState(false);
  const [showMediaOptions, setShowMediaOptions] = useState(false);
  const fileInputRef = useRef(null);
  const { user } = useAuth();

  const handleFileSelect = (e) => {
    const files = Array.from(e.target.files);
    const validFiles = files.filter(file => {
      const isValidType = file.type.startsWith('image/') || file.type.startsWith('video/');
      const isValidSize = file.size <= 50 * 1024 * 1024; // 50MB
      return isValidType && isValidSize;
    });

    if (validFiles.length === 0) {
      alert('Please select valid image or video files (max 50MB each)');
      return;
    }

    setMediaFiles(validFiles);
    
    // Create previews
    const previews = validFiles.map(file => ({
      url: URL.createObjectURL(file),
      type: file.type.startsWith('video/') ? 'video' : 'image'
    }));
    setMediaPreviews(previews);
  };

  const removeMedia = (index) => {
    const newFiles = mediaFiles.filter((_, i) => i !== index);
    const newPreviews = mediaPreviews.filter((_, i) => i !== index);
    setMediaFiles(newFiles);
    setMediaPreviews(newPreviews);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!content.trim() && mediaFiles.length === 0) {
      alert('Please add some content or media');
      return;
    }

    setLoading(true);
    const formData = new FormData();
    formData.append('content', content);
    
    mediaFiles.forEach(file => {
      formData.append('media', file);
    });

    try {
      const res = await axios.post('http://localhost:5000/api/posts', formData, {
        headers: {
          'Content-Type': 'multipart/form-data'
        }
      });
      
      const newPost = {
        ...res.data,
        user: {
          _id: user.id,
          username: user.username,
          name: user.name || user.username,
          profilePicture: user.profilePicture
        },
        likes: [],
        comments: []
      };
      
      onPostCreated(newPost);
      setContent('');
      setMediaFiles([]);
      setMediaPreviews([]);
      setShowMediaOptions(false);
    } catch (err) {
      console.error('Error creating post:', err);
      alert('Failed to create post. Please try again.');
    }
    setLoading(false);
  };

  return (
    <div className="create-post">
      <div className="create-post-header">
        <img src={user?.profilePicture || '/default-avatar.png'} alt="Profile" />
        <input
          type="text"
          placeholder={`What's on your mind, ${user?.name || user?.username}?`}
          value={content}
          onChange={(e) => setContent(e.target.value)}
          onClick={() => setShowMediaOptions(true)}
        />
      </div>

      {showMediaOptions && (
        <>
          {mediaPreviews.length > 0 && (
            <div className="media-previews">
              {mediaPreviews.map((preview, index) => (
                <div key={index} className="media-preview-item">
                  {preview.type === 'video' ? (
                    <video src={preview.url} controls className="preview-video" />
                  ) : (
                    <img src={preview.url} alt="Preview" className="preview-image" />
                  )}
                  <button className="remove-media" onClick={() => removeMedia(index)}>×</button>
                </div>
              ))}
            </div>
          )}

          <div className="create-post-actions">
            <button 
              className="action-btn photo-video-btn"
              onClick={() => fileInputRef.current.click()}
            >
              📸 Photo/Video
            </button>
            <input
              type="file"
              ref={fileInputRef}
              onChange={handleFileSelect}
              accept="image/*,video/*"
              multiple
              style={{ display: 'none' }}
            />
            <button 
              className="submit-btn" 
              onClick={handleSubmit}
              disabled={loading || (!content.trim() && mediaFiles.length === 0)}
            >
              {loading ? 'Posting...' : 'Post'}
            </button>
          </div>
        </>
      )}
    </div>
  );
};

export default CreatePost;
